#include <bits/stdc++.h>
using namespace std; struct P{long double x,y;};P operator-(P a,P b){return{a.x-b.x,a.y-b.y};}long double dot(P a,P b){return a.x*b.x+a.y*b.y;}long double norm(P a){return sqrtl(dot(a,a));}long double dist(P a,P b,P p){P v=b-a,w=p-a;if(dot(v,v)==0)return norm(w);long double t=max((long double)0,min((long double)1,dot(w,v)/dot(v,v)));return norm(P{p.x-(a.x+v.x*t),p.y-(a.y+v.y*t)});}int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;cout<<fixed<<setprecision(12);while(T--){P a,b,c;cin>>a.x>>a.y>>b.x>>b.y>>c.x>>c.y;cout<<dist(a,b,c)<<'\n';}}
